package io.github.finalparadox.client;
import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import io.github.finalparadox.entity.PumpkinBombEntity;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.block.BlockRenderDispatcher;import net.minecraft.client.renderer.entity.*;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.inventory.InventoryMenu;import net.minecraft.world.level.block.Blocks;
public final class PumpkinBombRenderer extends EntityRenderer<PumpkinBombEntity>{private final BlockRenderDispatcher blocks;public PumpkinBombRenderer(EntityRendererProvider.Context c){super(c);blocks=c.getBlockRenderDispatcher();shadowRadius=.2F;}@Override public ResourceLocation getTextureLocation(PumpkinBombEntity e){return InventoryMenu.BLOCK_ATLAS;}@Override public void render(PumpkinBombEntity e,float y,float partial,PoseStack p,MultiBufferSource b,int light){p.pushPose();p.translate(0,.25,0);p.mulPose(Axis.YP.rotationDegrees((e.tickCount+partial)*12));p.scale(.45F,.45F,.45F);p.translate(-.5,-.5,-.5);blocks.renderSingleBlock(Blocks.PUMPKIN.defaultBlockState(),p,b,light,OverlayTexture.NO_OVERLAY);p.popPose();super.render(e,y,partial,p,b,light);}}
